import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function toInt(value: unknown, fallback: number, label: string): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr03402Controller {
  @Get('/board-posts/:boardPostId/readers')
  async listBoardPostReaders(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자');
    const query = checks.queryOf(req.query);
    const boardPostId = req.params['boardPostId'];
    if (!/^\d+$/.test(boardPostId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '공지·게시물 ID가 올바르지 않습니다.');
    }
    const readStatus = query['readStatus'];
    if (readStatus !== undefined && readStatus !== null && readStatus !== '' && readStatus !== '읽음' && readStatus !== '안읽음') {
      throw new ApiError(400, 'VALIDATION_FAILED', '읽음 상태는 읽음 또는 안읽음이어야 합니다.');
    }
    const page = toInt(query['page'], 0, '쪽 번호');
    const requestedSize = toInt(query['size'], DEFAULT_SIZE, '쪽 크기');
    const size = Math.min(Math.max(requestedSize, 1), MAX_SIZE);

    let statusFilter = '';
    if (readStatus === '읽음') {
      statusFilter = 'AND l.post_read_log_id IS NOT NULL';
    } else if (readStatus === '안읽음') {
      statusFilter = 'AND l.post_read_log_id IS NULL';
    }

    return transaction(async (db) => {
      const posts = await db.query(
        'SELECT author_id AS "authorId", visibility_scope AS "visibilityScope" FROM board_post WHERE board_post_id = CAST(:postId AS bigint)',
        { postId: boardPostId },
      );
      if (posts.length === 0) {
        throw new ApiError(404, 'BOARD_POST_NOT_FOUND', '공지·게시물이 삭제되었거나 존재하지 않습니다.');
      }
      const post = posts[0];

      // 가정: 열람자 확인 권한의 부여 방식이 스펙에 없어 시스템 관리자 역할을 그 권한으로 본다.
      let isAdmin = true;
      try {
        user.require('시스템 관리자');
      } catch (e) {
        isAdmin = false;
      }
      const isAuthor = String(post.authorId) === String(user.id);
      if (!isAuthor && !isAdmin) {
        throw new ApiError(422, 'READER_VIEW_NOT_ALLOWED', '열람자를 확인할 권한이 없습니다.');
      }

      // 가정: 공개범위 '전체'는 재직자 전원이 대상이다.
      // 가정: '부서'·'개인'은 대상 테이블(post_audience)이 schema.sql에 없어 열람 기록이 있는 사람만 목록에 넣는다.
      const fromWhere =
        'FROM employee e ' +
        'JOIN department d ON d.department_id = e.department_id ' +
        'LEFT JOIN post_read_log l ON l.board_post_id = CAST(:postId AS bigint) AND l.employee_id = e.employee_id ' +
        'WHERE ((:scope = \'전체\' AND e.employment_status = \'재직자\') OR l.post_read_log_id IS NOT NULL) ' +
        statusFilter;
      const params = { postId: boardPostId, scope: post.visibilityScope };

      const counted = await db.query('SELECT COUNT(*) AS "total" ' + fromWhere, params);
      const total = Number(counted[0].total);

      const items = await db.query(
        'SELECT e.employee_id AS "employeeId", e.name AS "employeeName", d.name AS "departmentName", ' +
          'l.read_at AS "readAt", ' +
          'CASE WHEN l.post_read_log_id IS NULL THEN \'안읽음\' ELSE \'읽음\' END AS "readStatus" ' +
          fromWhere +
          ' ORDER BY (l.post_read_log_id IS NULL), e.name, e.employee_id ' +
          'LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, limit: size, offset: page * size },
      );
      return { items, page, size, total };
    });
  }
}

