import { useState } from 'react';
import { Band, Badge, DataTable, DateText, ErrorText, Field, Filters, LookupSelect, Pager, RefName, Select, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr03402Page({ role, notify }: PageProps) {
  const [postId, setPostId] = useState<number | string>('');
  const [readStatus, setReadStatus] = useState('');
  const [applied, setApplied] = useState({ postId: '' as number | string, readStatus: '' });
  const [page, setPage] = useState(0);

  const { data, error, loading } = useData<Page | undefined>(async () => {
    if (applied.postId === '') {
      return undefined;
    }
    return call<Page>('GET', '/board-posts/' + applied.postId + '/readers', role, undefined, {
      readStatus: applied.readStatus,
      page,
      size: SIZE,
    });
  }, [applied, page, role]);

  const search = () => {
    if (postId === '') {
      notify('열람 현황을 볼 공지·게시물을 먼저 선택해 주세요.');
      return;
    }
    setPage(0);
    setApplied({ postId, readStatus });
  };

  const reset = () => {
    setPostId('');
    setReadStatus('');
    setPage(0);
    setApplied({ postId: '', readStatus: '' });
  };

  const rows: Row[] = data ? data.items : [];

  return (
    <div className="doc">
      <section className="box">
        <h2>공지·게시물 열람자 확인</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="공지·게시물" required>
            <LookupSelect table="board_post" role={role} value={postId} onChange={setPostId} placeholder="공지·게시물 선택" />
          </Field>
          <Field label="읽음 상태">
            <Select
              value={readStatus}
              onChange={setReadStatus}
              options={[['읽음', '읽음'], ['안읽음', '안읽음']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
      </section>
      <section className="box">
        <h2>열람 현황</h2>
        {error ? <ErrorText text={error} /> : null}
        {applied.postId === '' ? (
          <p>공지·게시물을 선택하고 조회하면 열람자와 미열람자를 볼 수 있습니다.</p>
        ) : (
          <>
            <Band total={data ? data.total : 0} />
            <DataTable
              columns={[
                { key: 'employeeName', label: '임직원명' },
                { key: 'departmentName', label: '부서명' },
                { key: 'readStatus', label: '읽음 상태', render: (r) => <Badge value={r.readStatus} /> },
                { key: 'readAt', label: '열람 일시', render: (r) => (r.readAt ? <DateText value={r.readAt} time /> : <span>-</span>) },
              ]}
              rows={rows}
              empty={loading ? '불러오는 중입니다.' : '조건에 맞는 대상자가 없습니다.'}
            />
            <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
          </>
        )}
      </section>
    </div>
  );
}
